export const netHpp = "#pragma once                                                    // include this header only once per build\n#include <cstddef>                                              // std::size_t\n#include <cstdint>                                              // fixed-size integers\n#include <cstring>                                              // std::memcpy for float <-> bytes\n#include <initializer_list>                                     // lets send_call take { a, b, c }\n#include <map>                                                  // std::map for the inventory\n#include <string>                                               // std::string\n#include <vector>                                               // std::vector\n#include <enet/enet.h>                                          // the patched ENet fork\n\nusing u8  = std::uint8_t;                                       // short name for an unsigned byte\nusing u16 = std::uint16_t;                                      // short name for an unsigned 2-byte number\nusing u32 = std::uint32_t;                                      // short name for an unsigned 4-byte number\nusing i32 = std::int32_t;                                       // short name for a signed 4-byte number\n\nstruct blob {                                                   // a byte buffer that writes numbers in little-endian\n    std::vector<u8> bytes;                                      // the bytes written so far\n\n    void u8v(u8 v) { bytes.push_back(v); }                      // append one byte\n    void u16v(u16 v) { u8v(u8(v)); u8v(u8(v >> 8)); }          // append 2 bytes, low byte first\n    void i16v(i32 v) { u16v(u16(v)); }                          // signed 2 bytes share the same bits\n    void u32v(u32 v) { for (int i = 0; i < 4; ++i) u8v(u8(v >> (8 * i))); } // append 4 bytes, low byte first\n    void i32v(i32 v) { u32v(u32(v)); }                          // signed 4 bytes share the same bits\n    void f32v(float v) { u32 raw; std::memcpy(&raw, &v, 4); u32v(raw); } // copy the float's bits, then write them\n    void str(const std::string &s) {                            // length-prefixed string\n        i32v(i32(s.size()));                                    // 4-byte length first\n        bytes.insert(bytes.end(), s.begin(), s.end());          // then the characters\n    }                                                           // end of str\n    void append(const blob &o) { bytes.insert(bytes.end(), o.bytes.begin(), o.bytes.end()); } // glue another blob on\n};                                                              // end of blob\n\nstruct game_packet {                                            // message type 4: a 56-byte header + optional extra data\n    i32 type = 0;                                               // what kind of game packet (0x03 tile change, 0x04 map ...)\n    i32 netid = -1;                                             // which player it is about\n    i32 uid = -1;                                               // spare id field\n    i32 state = 0;                                              // flags, 0x08 means \"extra data follows\"\n    float count = 0.f;                                          // misc float\n    i32 id = 0;                                                 // item id (18 fist, 32 wrench)\n    float x = 0.f, y = 0.f;                                     // position in pixels\n    float sx = 0.f, sy = 0.f;                                   // speed\n    float extra_f = 0.f;                                        // misc float\n    i32 tile_x = 0, tile_y = 0;                                 // tile the packet is about\n    blob extra;                                                 // data after the header\n\n    blob encode() const {                                       // turn the struct into wire bytes\n        blob b;                                                 // output buffer\n        b.i32v(4);                                              // message type 4 = GAME_PACKET\n        b.i32v(type);                                           // header offset 0\n        b.i32v(netid);                                          // header offset 4\n        b.i32v(uid);                                            // header offset 8\n        b.i32v(state);                                          // header offset 12\n        b.f32v(count);                                          // header offset 16\n        b.i32v(id);                                             // header offset 20\n        b.f32v(x); b.f32v(y);                                   // header offsets 24 and 28\n        b.f32v(sx); b.f32v(sy);                                 // header offsets 32 and 36\n        b.f32v(extra_f);                                        // header offset 40\n        b.i32v(tile_x); b.i32v(tile_y);                         // header offsets 44 and 48\n        b.i32v(i32(extra.bytes.size()));                        // header offset 52: size of the extra data\n        b.append(extra);                                        // the extra data itself\n        return b;                                               // done\n    }                                                           // end of encode\n};                                                              // end of game_packet\n\nstruct peer {                                                   // our own data attached to every ENet connection\n    i32 user_id = 0;                                            // database account id (0 = not logged in)\n    i32 netid = -1;                                             // id other players see in the current world\n    std::string growid;                                         // account name\n    std::string world;                                          // current world name, empty = in the menu\n    float x = 0.f, y = 0.f;                                     // position in pixels\n    std::map<u16, u8> inventory;                                // item id -> amount carried\n};                                                              // end of peer\n\nstruct variant {                                                // one argument of a function call sent to the client\n    u8 kind = 2;                                                // 1 float, 2 string, 3 vec2, 5 uint, 9 int\n    float f = 0.f, g = 0.f;                                     // float / vec2 values\n    i32 n = 0;                                                  // int / uint value\n    std::string s;                                              // string value\n};                                                              // end of variant\n\nvariant Vstr(std::string v);                                    // make a string argument\nvariant Vnum(i32 v);                                            // make a signed int argument\nvariant Vuint(u32 v);                                           // make an unsigned int argument\nvariant Vflt(float v);                                          // make a float argument\nvariant Vvec(float x, float y);                                 // make a 2-float argument\n\nextern ENetHost *g_host;                                        // the one ENet server host, set in main()\n\nvoid send_raw(ENetPeer *peer, const blob &b);                   // send bytes reliably\nvoid send_text(ENetPeer *peer, i32 message_type, const std::string &text); // send message type 2/3 text\nblob make_call(i32 netid, std::initializer_list<variant> args); // build the bytes of a client function call\nvoid send_call(ENetPeer *peer, i32 netid, std::initializer_list<variant> args); // build + send a client function call\nvoid send_items(ENetPeer *peer);                                // send the whole items.dat\nvoid send_inventory(ENetPeer *ep, const ::peer *p);            // send the backpack\nvoid broadcast_world(const std::string &world, const blob &b, ENetPeer *except); // send to everyone in a world\nvoid handle_message(ENetPeer *peer, const u8 *data, std::size_t size); // route one incoming packet\nstd::string field(const std::string &text, const std::string &key); // read key|value or key=value\n\nbool on_login(peer *p, ENetPeer *ep, const std::string &text); // ltoken login (before reconnect)\nvoid on_logon(peer *p, ENetPeer *ep, const std::string &text); // tankIDName message (after reconnect)\nvoid on_action(peer *p, ENetPeer *ep, const std::string &text); // action|... text commands\nvoid on_join(peer *p, ENetPeer *ep, const std::string &name);  // join a world\nvoid on_leave(peer *p, ENetPeer *ep);                           // leave the current world\nvoid on_tile_change(peer *p, ENetPeer *ep, const game_packet &gp); // punch or place\n";

export const itemsHpp = "#pragma once                                                    // include this header only once per build\n#include <cstdint>                                              // fixed-size integers like uint16_t\n#include <string>                                               // std::string for names\n#include <vector>                                               // std::vector for the item list and raw bytes\n\nenum item_type : std::uint8_t {                                 // the \"type\" byte stored in items.dat (subset used by this starter)\n    T_FIST = 0x00,                                              // the fist (item 18)\n    T_WRENCH = 0x01,                                            // the wrench (item 32)\n    T_CONSUMEABLE = 0x08,                                       // items that are used up, not placed\n    T_MAIN_DOOR = 0x0d,                                         // the white door at spawn\n    T_STRONG = 0x0f,                                            // too strong to break (bedrock)\n    T_FOREGROUND = 0x11,                                        // normal solid blocks\n    T_BACKGROUND = 0x12,                                        // background blocks go in the bg layer\n    T_SEED = 0x13,                                              // seeds\n    T_CLOTHING = 0x14,                                          // wearable items\n};                                                              // end of item_type\n\nstruct item_info {                                              // everything this starter keeps about ONE item\n    std::uint16_t id = 0;                                       // item id, also its index in the list\n    std::uint8_t property = 0;                                  // flag byte (editable, untradeable ...)\n    std::uint8_t cat = 0;                                       // category flag byte\n    std::uint8_t type = 0;                                      // one of item_type above\n    std::string name;                                           // readable name after un-XOR\n    std::int32_t ingredient = 0;                                // splice/recipe helper value\n    std::uint8_t collision = 0;                                 // 0 = walk through, 1 = solid, 2 = platform ...\n    std::uint8_t hits = 0;                                      // punches needed to break (file stores hits * 6)\n    std::int32_t hit_reset = 0;                                 // seconds until the damage on a tile heals\n    std::uint8_t cloth_type = 10;                               // clothing slot, 10 = not clothing\n    std::int16_t rarity = 0;                                    // rarity number shown in the item info\n    std::int32_t tick = 0;                                      // grow time for trees, in seconds\n    std::string info;                                           // description text (items.dat version 22 and newer)\n};                                                              // end of item_info\n\nstruct items_db {                                               // the whole decoded file\n    std::uint16_t version = 0;                                  // items.dat version number from the file header\n    std::uint32_t count = 0;                                    // how many items the header promises\n    std::uint32_t hash = 0;                                     // proton hash the client compares to know if its copy is old\n    std::vector<std::uint8_t> raw;                              // the untouched file bytes, sent to the client later\n    std::vector<item_info> list;                                // decoded items, list[id] is item id\n};                                                              // end of items_db\n\nextern items_db g_items;                                        // one global database, filled by items_load()\n\nbool items_load(const std::string &path, std::string &error);  // read + decode a file, false and a message on failure\nconst item_info &id_to_item(std::uint16_t id);                  // safe lookup, unknown ids return item 0\nstd::uint32_t proton_hash(const std::uint8_t *data, std::size_t size); // the client's simple rolling hash\n";

export const itemsCpp = "#include \"items.hpp\"                                            // our own declarations\n#include <fstream>                                              // std::ifstream reads the file from disk\n#include <iterator>                                             // std::istreambuf_iterator for reading all bytes\n#include <stdexcept>                                            // std::runtime_error to abort on bad data\n\nitems_db g_items;                                               // define the global declared in the header\n\nnamespace {                                                     // helpers below are private to this file\n\nstruct reader {                                                 // walks through bytes and refuses to read past the end\n    const std::vector<std::uint8_t> &d;                         // the bytes being read\n    std::size_t pos;                                            // current read position\n\n    void need(std::size_t n) const {                            // make sure n more bytes exist\n        if (pos + n > d.size())                                 // would we read beyond the end?\n            throw std::runtime_error(\"items.dat ended early or has an unsupported layout\"); // stop with a clear message\n    }                                                           // end of need\n\n    std::uint8_t u8() { need(1); return d[pos++]; }             // read 1 byte\n    std::uint16_t u16() {                                       // read 2 bytes, little-endian\n        need(2);                                                // check there are 2 bytes left\n        std::uint16_t v = std::uint16_t(d[pos] | (d[pos + 1] << 8)); // low byte first, then high byte\n        pos += 2;                                               // move forward\n        return v;                                               // hand the value back\n    }                                                           // end of u16\n    std::uint32_t u32() {                                       // read 4 bytes, little-endian\n        need(4);                                                // check there are 4 bytes left\n        std::uint32_t v = 0;                                    // start from zero\n        for (int i = 0; i < 4; ++i) v |= std::uint32_t(d[pos + i]) << (8 * i); // add each byte at its shifted place\n        pos += 4;                                               // move forward\n        return v;                                               // hand the value back\n    }                                                           // end of u32\n    void skip(std::size_t n) { need(n); pos += n; }             // jump over n bytes we do not care about\n    void skip_str() { skip(u16()); }                            // skip a string stored as [u16 length][bytes]\n    std::string str() {                                         // read a plain (not XORed) string\n        std::uint16_t len = u16();                              // first the length\n        need(len);                                              // then make sure the bytes exist\n        std::string s(reinterpret_cast<const char *>(&d[pos]), len); // copy the bytes into a std::string\n        pos += len;                                             // move forward\n        return s;                                               // hand it back\n    }                                                           // end of str\n};                                                              // end of reader\n\n}                                                               // end of anonymous namespace\n\nstd::uint32_t proton_hash(const std::uint8_t *data, std::size_t size) { // same loop as Proton SDK's HashString\n    std::uint32_t h = 0x55555555;                               // fixed starting value\n    for (std::size_t i = 0; i < size; ++i)                      // visit every byte\n        h = (h >> 27) + (h << 5) + data[i];                     // rotate-ish mix, wraps on overflow on purpose\n    return h;                                                   // the final hash\n}                                                               // end of proton_hash\n\nconst item_info &id_to_item(std::uint16_t id) {                 // lookup that never crashes\n    if (id >= g_items.list.size()) return g_items.list.at(0);   // out of range falls back to item 0 (list must not be empty)\n    return g_items.list[id];                                    // normal case\n}                                                               // end of id_to_item\n\nbool items_load(const std::string &path, std::string &error) { // decode the whole file\n    std::ifstream in(path, std::ios::binary);                   // open as binary so Windows does not change bytes\n    if (!in) { error = \"cannot open \" + path; return false; }   // missing file is the most common mistake\n    std::vector<std::uint8_t> bytes((std::istreambuf_iterator<char>(in)), {}); // read every byte into memory\n\n    items_db db;                                                // build into a temporary, replace the global only on success\n    db.raw = bytes;                                             // keep the original bytes for sending to the client\n    db.hash = proton_hash(bytes.data(), bytes.size());          // hash of the file, goes into OnSuperMainStartAcceptLogon\n\n    try {                                                       // the reader throws when the layout is not what we expect\n        reader r{db.raw, 0};                                    // start reading at byte 0\n        db.version = r.u16();                                   // header: 2 bytes version\n        db.count = r.u32();                                     // header: 4 bytes item count\n        if (db.count > 100000) throw std::runtime_error(\"item count looks wrong, wrong file?\"); // sanity limit\n        db.list.reserve(db.count);                              // avoid re-allocations while we push\n\n        const std::string key = \"PBG892FXX982ABC*\";            // XOR key the game uses to hide item names\n\n        for (std::uint32_t n = 0; n < db.count; ++n) {          // decode items one by one\n            item_info it;                                       // the item we are filling in\n            it.id = std::uint16_t(r.u32());                     // id is stored in 4 bytes, ids fit in 2\n            it.property = r.u8();                               // flag byte\n            it.cat = r.u8();                                    // category byte\n            it.type = r.u8();                                   // item type byte\n            r.skip(1);                                          // material byte, not needed\n\n            std::uint16_t len = r.u16();                        // name length\n            r.need(len);                                        // make sure the name bytes exist\n            it.name.resize(len);                                // allocate the name\n            for (std::uint16_t i = 0; i < len; ++i)             // un-XOR every character\n                it.name[i] = char(r.d[r.pos + i] ^ key[(i + it.id) % key.size()]); // key position depends on the item id\n            r.skip(len);                                        // move past the name\n\n            r.skip_str();                                       // texture file name\n            r.skip(4);                                          // texture hash\n            r.skip(1);                                          // visual effect byte\n            it.ingredient = std::int32_t(r.u32());              // ingredient / splice value\n            r.skip(4);                                          // 4 single-byte values (storage, flags ...)\n            it.collision = r.u8();                              // collision type\n            it.hits = r.u8();                                   // stored hits value\n            if (it.hits != 0) it.hits /= 6;                     // the file stores hits * 6, divide to get real punches\n            it.hit_reset = std::int32_t(r.u32());               // heal time in seconds\n\n            if (it.type == T_CLOTHING) it.cloth_type = r.u8();  // clothing slot only exists for clothing\n            else r.skip(1);                                     // otherwise the byte is unused\n            it.rarity = std::int16_t(r.u16());                  // rarity\n            r.skip(1);                                          // max amount you can carry\n            r.skip_str();                                       // audio file name\n            r.skip(4);                                          // audio volume\n            r.skip(4);                                          // pet / animation value\n            r.skip(4);                                          // 4 more fixed bytes\n            for (int s = 0; s < 4; ++s) r.skip_str();           // four strings: pet name, prefix, suffix, ability\n            r.skip(16);                                         // 16 fixed bytes\n            it.tick = std::int32_t(r.u32());                    // grow time (trees) in seconds\n            r.skip(2); r.skip(2);                               // two shorts we ignore\n            for (int s = 0; s < 3; ++s) r.skip_str();           // three more strings\n            r.skip(80);                                         // an 80-byte block of tinting/ranges\n\n            if (db.version >= 0x0b) r.skip_str();               // version 11: extra string\n            if (db.version >= 0x0c) { r.skip(4); r.skip(9); }   // version 12: int + 9 bytes\n            if (db.version >= 0x0d) r.skip(4);                  // version 13: int\n            if (db.version >= 0x0e) r.skip(4);                  // version 14: int\n            if (db.version >= 0x0f) { r.skip(25); r.skip_str(); } // version 15: 25 bytes + string\n            if (db.version >= 0x10) r.skip_str();               // version 16: string\n            if (db.version >= 0x11) r.skip(4);                  // version 17: int\n            if (db.version >= 0x12) r.skip(4);                  // version 18: int\n            if (db.version >= 0x13) r.skip(9);                  // version 19: 9 bytes\n            if (db.version >= 0x15) r.skip(2);                  // version 21: short\n            if (db.version >= 0x16) it.info = r.str();          // version 22: item description\n            if (db.version >= 0x17) r.skip(4);                  // version 23: two seed ids (2 shorts)\n            if (db.version >= 0x18) r.skip(1);                  // version 24: byte\n            if (db.version >= 0x19) {                           // version 25: optional punch effect\n                std::uint16_t l = r.u16();                      // its length\n                if (l > 6) r.skip(l);                           // only present when longer than the empty form\n                r.skip(4);                                      // always followed by an int\n            }                                                   // end of version 25 block\n            if (db.version >= 0x1a) r.skip(1);                  // version 26: byte\n            if (db.version == 0x1b) {                           // version 27 only: immortal item marker\n                std::uint16_t l = r.u16();                      // length of the marker\n                if (l > 0) r.skip(1);                           // one byte follows when not empty\n            }                                                   // end of version 27 block\n\n            db.list.push_back(std::move(it));                   // store the finished item\n        }                                                       // end of item loop\n    } catch (const std::exception &e) {                         // any layout problem lands here\n        error = e.what();                                       // give the message to the caller\n        return false;                                           // nothing was stored\n    }                                                           // end of try/catch\n\n    if (db.list.empty()) { error = \"items.dat had no items\"; return false; } // an empty list would break id_to_item\n    g_items = std::move(db);                                    // success: publish the decoded database\n    return true;                                                // tell the caller it worked\n}                                                               // end of items_load\n";

export const itemsDumpCpp = "#include \"../src/items.hpp\"                                     // the decoder\n#include <algorithm>                                            // std::transform for lowercase\n#include <cstdio>                                               // printf\n#include <string>                                               // std::string\n\nint main(int argc, char **argv) {                               // usage: items_dump items.dat [search words]\n    std::string error;                                          // filled when decoding fails\n    const char *path = argc > 1 ? argv[1] : \"items.dat\";        // first argument is the file, default items.dat\n    if (!items_load(path, error)) {                             // try to decode it\n        std::printf(\"FAILED: %s\\n\", error.c_str());             // show why\n        return 1;                                               // non-zero exit = test failed\n    }                                                           // end of failure branch\n    std::printf(\"version=%u count=%u hash=%u bytes=%zu\\n\",      // header summary\n                g_items.version, g_items.count, g_items.hash, g_items.raw.size()); // values to compare with the guide's Items tab\n    const std::string needle = argc > 2 ? argv[2] : \"\";         // optional name filter\n    int shown = 0;                                              // how many rows printed\n    for (const item_info &it : g_items.list) {                  // walk every item\n        std::string a = it.name, b = needle;                    // copies we can lowercase\n        std::transform(a.begin(), a.end(), a.begin(), ::tolower); // lowercase the item name\n        std::transform(b.begin(), b.end(), b.begin(), ::tolower); // lowercase the search text\n        if (!needle.empty() && a.find(b) == std::string::npos) continue; // skip non-matches\n        std::printf(\"%5u  %-28s type=0x%02x hits=%u rarity=%d\\n\", // one readable row\n                    it.id, it.name.c_str(), it.type, it.hits, it.rarity); // the fields we decoded\n        if (++shown >= 25) break;                               // 25 rows is enough for a smoke test\n    }                                                           // end of loop\n    return 0;                                                   // success\n}                                                               // end of main\n";

export const protocolCpp = "#include \"net.hpp\"                                              // shared declarations\n#include \"items.hpp\"                                            // g_items for send_items\n#include <algorithm>                                            // std::min\n\nENetHost *g_host = nullptr;                                     // define the global host pointer\n\nvariant Vstr(std::string v) { variant r; r.kind = 2; r.s = std::move(v); return r; } // string argument\nvariant Vnum(i32 v) { variant r; r.kind = 9; r.n = v; return r; } // signed int argument\nvariant Vuint(u32 v) { variant r; r.kind = 5; r.n = i32(v); return r; } // unsigned int argument\nvariant Vflt(float v) { variant r; r.kind = 1; r.f = v; return r; } // float argument\nvariant Vvec(float x, float y) { variant r; r.kind = 3; r.f = x; r.g = y; return r; } // vec2 argument\n\nvoid send_raw(ENetPeer *peer, const blob &b) {                  // low-level send\n    ENetPacket *packet = enet_packet_create(b.bytes.data(), b.bytes.size(), ENET_PACKET_FLAG_RELIABLE); // copy bytes into an ENet packet\n    if (!packet) return;                                        // out of memory, give up quietly\n    if (enet_peer_send(peer, 0, packet) != 0) enet_packet_destroy(packet); // on failure we still own the packet, free it\n}                                                               // end of send_raw\n\nvoid send_text(ENetPeer *peer, i32 message_type, const std::string &text) { // types 2 and 3 are plain text\n    blob b;                                                     // output buffer\n    b.i32v(message_type);                                       // first 4 bytes: the message type\n    b.bytes.insert(b.bytes.end(), text.begin(), text.end());    // then the text\n    b.u8v(0);                                                   // trailing NUL, the client expects it\n    send_raw(peer, b);                                          // ship it\n}                                                               // end of send_text\n\nblob make_call(i32 netid, std::initializer_list<variant> args) { // build an OnXxx function call without sending it\n    blob extra;                                                 // the variant list goes in the extra data\n    extra.u8v(u8(args.size()));                                 // how many arguments\n    u8 index = 0;                                               // argument number\n    for (const variant &v : args) {                             // write each argument\n        extra.u8v(index++);                                     // its index\n        extra.u8v(v.kind);                                      // its type tag\n        if (v.kind == 1) extra.f32v(v.f);                       // float\n        else if (v.kind == 2) extra.str(v.s);                   // string\n        else if (v.kind == 3) { extra.f32v(v.f); extra.f32v(v.g); } // two floats\n        else extra.i32v(v.n);                                   // 4-byte integer (kinds 5 and 9)\n    }                                                           // end of argument loop\n    game_packet gp;                                             // wrap it in a game packet\n    gp.type = 0x01;                                             // 0x01 = CALL_FUNCTION\n    gp.netid = netid;                                           // who the call is about (-1 = nobody)\n    gp.state = 0x08;                                            // extra data follows\n    gp.extra = extra;                                           // attach the variant list\n    return gp.encode();                                         // the finished bytes\n}                                                               // end of make_call\n\nvoid send_call(ENetPeer *peer, i32 netid, std::initializer_list<variant> args) { // build and send in one step\n    send_raw(peer, make_call(netid, args));                     // ship it\n}                                                               // end of send_call\n\nvoid send_items(ENetPeer *peer) {                               // answer to action|refresh_item_data\n    game_packet gp;                                             // wrap the file in a game packet\n    gp.type = 0x10;                                             // 0x10 = SEND_ITEM_DATABASE_DATA\n    gp.state = 0x08;                                            // extra data follows\n    gp.extra.bytes = g_items.raw;                               // the untouched items.dat bytes\n    send_raw(peer, gp.encode());                                // ship it\n}                                                               // end of send_items\n\nvoid send_inventory(ENetPeer *peer, const ::peer *p) {          // the backpack contents\n    game_packet gp;                                             // wrap it in a game packet\n    gp.type = 0x09;                                             // 0x09 = SEND_INVENTORY_STATE\n    gp.netid = p->netid;                                        // whose backpack\n    gp.state = 0x08;                                            // extra data follows\n    gp.extra.u8v(1);                                            // flag: big backpack enabled\n    gp.extra.i32v(32);                                          // number of slots\n    gp.extra.i16v(i32(p->inventory.size()));                    // number of filled slots\n    for (const auto &[id, amount] : p->inventory) {             // one entry per item\n        gp.extra.i16v(id);                                      // item id\n        gp.extra.u8v(amount);                                   // how many\n        gp.extra.u8v(0);                                        // padding byte (not equipped)\n    }                                                           // end of slot loop\n    send_raw(peer, gp.encode());                                // ship it\n}                                                               // end of send_inventory\n\nvoid broadcast_world(const std::string &world, const blob &b, ENetPeer *except) { // everyone in one world\n    for (size_t i = 0; i < g_host->peerCount; ++i) {            // walk all connection slots\n        ENetPeer *other = &g_host->peers[i];                    // one slot\n        if (other == except || other->state != ENET_PEER_STATE_CONNECTED) continue; // skip the sender and empty slots\n        const ::peer *op = static_cast<::peer *>(other->data);  // our data for that connection\n        if (op && op->world == world) send_raw(other, b);       // same world -> send\n    }                                                           // end of loop\n}                                                               // end of broadcast_world\n\nstd::string field(const std::string &text, const std::string &key) { // find key|value or key=value\n    for (const char separator : {'|', '='}) {                   // both formats are used by the game\n        const std::string needle = key + separator;             // e.g. \"name|\"\n        for (std::size_t at = text.find(needle); at != std::string::npos; at = text.find(needle, at + 1)) { // every match\n            if (at != 0 && text[at - 1] != '\\n') continue;      // the key must start a line\n            at += needle.size();                                // jump to the value\n            const std::size_t end = text.find_first_of(\"\\n&\", at); // value ends at newline or &\n            return text.substr(at, end == std::string::npos ? end : end - at); // cut the value out\n        }                                                       // end of match loop\n    }                                                           // end of separator loop\n    return {};                                                  // key not found\n}                                                               // end of field\n\nvoid handle_message(ENetPeer *ep, const u8 *data, std::size_t size) { // every incoming packet lands here\n    if (size < 4) return;                                       // too short to hold a message type\n    i32 message_type = 0;                                       // will hold the first 4 bytes\n    std::memcpy(&message_type, data, 4);                        // read them\n    peer *p = static_cast<peer *>(ep->data);                    // our data for this connection\n    if (!p) return;                                             // unknown connection\n    if (message_type == 2) {                                    // type 2 = login text\n        const std::string text(reinterpret_cast<const char *>(data + 4), size - 4); // text after the type\n        if (text.find(\"ltoken|\") != std::string::npos) on_login(p, ep, text); // first connection: token login\n        else on_logon(p, ep, text);                             // second connection: tankIDName\n    } else if (message_type == 3) {                             // type 3 = action text\n        on_action(p, ep, std::string(reinterpret_cast<const char *>(data + 4), size - 4)); // pass the text on\n    } else if (message_type == 4 && size >= 60) {               // type 4 = game packet (4 + 56 header bytes)\n        const u8 *h = data + 4;                                 // start of the 56-byte header\n        game_packet gp;                                         // decoded copy\n        std::memcpy(&gp.type, h + 0, 4);                        // header offset 0\n        std::memcpy(&gp.netid, h + 4, 4);                       // header offset 4\n        std::memcpy(&gp.uid, h + 8, 4);                         // header offset 8\n        std::memcpy(&gp.state, h + 12, 4);                      // header offset 12\n        std::memcpy(&gp.count, h + 16, 4);                      // header offset 16\n        std::memcpy(&gp.id, h + 20, 4);                         // header offset 20\n        std::memcpy(&gp.x, h + 24, 4);                          // header offset 24\n        std::memcpy(&gp.y, h + 28, 4);                          // header offset 28\n        std::memcpy(&gp.sx, h + 32, 4);                         // header offset 32\n        std::memcpy(&gp.sy, h + 36, 4);                         // header offset 36\n        std::memcpy(&gp.extra_f, h + 40, 4);                    // header offset 40\n        std::memcpy(&gp.tile_x, h + 44, 4);                     // header offset 44\n        std::memcpy(&gp.tile_y, h + 48, 4);                     // header offset 48\n        i32 extra_length = 0;                                   // size of the extra data\n        std::memcpy(&extra_length, h + 52, 4);                  // header offset 52\n        const std::size_t take = std::min<std::size_t>(extra_length > 0 ? std::size_t(extra_length) : 0, size - 60); // never trust the length\n        gp.extra.bytes.assign(h + 56, h + 56 + take);           // copy the extra data\n        if ((gp.type & 0xff) == 0x03) on_tile_change(p, ep, gp); // 0x03 = punch/place\n    }                                                           // end of type 4\n}                                                               // end of handle_message\n";

export const mainCpp = "#include \"db.hpp\"                                               // db_open\n#include \"https.hpp\"                                            // https_run\n#include \"items.hpp\"                                            // items_load\n#include \"net.hpp\"                                              // ENet + packet helpers\n\n#include <csignal>                                              // std::signal for Ctrl+C\n#include <cstdio>                                               // std::puts\n#include <thread>                                               // run the HTTPS responder beside ENet\n\nstatic volatile std::sig_atomic_t g_stop = 0;                   // set to 1 when Ctrl+C is pressed\nstatic void on_signal(int) { g_stop = 1; }                      // signal handler only flips the flag\n\nint main() {                                                    // program starts here\n    std::signal(SIGINT, on_signal);                             // Ctrl+C asks the loop to stop\n\n    std::string error;                                          // filled by items_load on failure\n    if (!items_load(\"items.dat\", error)) {                      // decode items.dat from the working directory\n        std::printf(\"items.dat: %s\\n\", error.c_str());          // tell the user what went wrong\n        return 1;                                               // the server cannot run without item data\n    }                                                           // end of items check\n    std::printf(\"items.dat v%u: %u items, hash %u\\n\", g_items.version, g_items.count, g_items.hash); // proof it decoded\n\n    if (!db_open(\"127.0.0.1\", \"root\", \"\", \"gtps\")) {            // connect to MariaDB / MySQL\n        std::puts(\"mysql: check the server, the credentials and the gtps database\"); // typical causes\n        return 1;                                               // stop, nothing works without the database\n    }                                                           // end of db check\n\n    if (enet_initialize() != 0) return 1;                       // start ENet, 0 means success\n\n    std::thread(https_run).detach();                            // TLS responder on :443 runs forever in the background\n\n    ENetAddress address{};                                      // where ENet listens\n    address.type = ENET_ADDRESS_TYPE_IPV4;                      // IPv4 only\n    address.port = 17091;                                       // the game port from server_data\n    enet_address_set_host_ip(&address, \"127.0.0.1\");            // listen on this machine\n\n    g_host = enet_host_create(ENET_ADDRESS_TYPE_IPV4, &address, 64, 2, 0, 0); // up to 64 peers, 2 channels, no bandwidth limit\n    if (!g_host) {                                              // creation failed\n        std::puts(\"enet: cannot bind udp/17091\");               // usually the port is taken\n        return 1;                                               // stop\n    }                                                           // end of host check\n\n    g_host->usingNewPacketForServer = true;                     // patch 1 of 3: new packet format\n    g_host->checksum = enet_crc32;                              // patch 2 of 3: CRC32 checksum\n    enet_host_compress_with_range_coder(g_host);                // patch 3 of 3: range coder compression\n\n    std::puts(\"https://127.0.0.1/growtopia/server_data.php\");   // where the client asks for the address\n    std::puts(\"enet udp/17091\");                                // where the game connects\n\n    ENetEvent event{};                                          // filled by enet_host_service\n    while (!g_stop) {                                           // main loop until Ctrl+C\n        if (enet_host_service(g_host, &event, 50) <= 0) continue; // wait up to 50 ms for something to happen\n\n        if (event.type == ENET_EVENT_TYPE_CONNECT) {            // a client connected\n            event.peer->data = new peer{};                      // give it our data object\n            send_text(event.peer, 1, \"\");                       // SERVER_HELLO: \"send me your login\"\n        } else if (event.type == ENET_EVENT_TYPE_RECEIVE) {     // a packet arrived\n            handle_message(event.peer, event.packet->data, event.packet->dataLength); // route it\n            enet_packet_destroy(event.packet);                  // we own the packet, free it\n        } else if (event.type == ENET_EVENT_TYPE_DISCONNECT) {  // a client left\n            peer *p = static_cast<peer *>(event.peer->data);    // our data for it\n            if (p) on_leave(p, event.peer);                     // tell the world it is gone\n            delete p;                                           // free our data\n            event.peer->data = nullptr;                         // never leave a dangling pointer\n        }                                                       // end of event types\n    }                                                           // end of main loop\n\n    enet_host_destroy(g_host);                                  // close the host\n    enet_deinitialize();                                        // shut ENet down\n    std::puts(\"stopped\");                                       // goodbye\n}                                                               // end of main\n";

export const httpsHpp = "#pragma once                                                    // include once\n\nvoid https_run();                                               // blocking TLS responder for server_data.php, run it on its own thread\n";

export const httpsCpp = "#include \"https.hpp\"                                            // our declaration\n#include <cstdio>                                               // fprintf\n#include <string>                                               // std::string\n#include <openssl/ssl.h>                                        // TLS\n\n#ifdef _WIN32                                                   // Windows sockets\n    #include <winsock2.h>                                       // socket API\n    #include <ws2tcpip.h>                                       // address helpers\n    using socket_t = SOCKET;                                    // Windows socket type\n    #define CLOSE_SOCKET closesocket                            // Windows close function\n#else                                                           // Linux / macOS sockets\n    #include <arpa/inet.h>                                      // htons\n    #include <netinet/in.h>                                     // sockaddr_in\n    #include <sys/socket.h>                                     // socket, bind, listen, accept\n    #include <unistd.h>                                         // close\n    using socket_t = int;                                       // POSIX socket type\n    #define INVALID_SOCKET (-1)                                 // POSIX failure value\n    #define CLOSE_SOCKET close                                  // POSIX close function\n#endif                                                          // end of platform switch\n\nstatic const char *kServerData =                                // what the client reads to find the game server\n    \"server|127.0.0.1\\n\"                                        // game server address\n    \"port|17091\\n\"                                              // game server UDP port\n    \"type|1\\n\"                                                  // server type\n    \"type2|1\\n\"                                                 // second server type\n    \"#maint|Server under maintenance. Please try again later.\\n\" // shown only when maintenance is on\n    \"loginurl|127.0.0.1\\n\"                                      // host of the login backend\n    \"meta|gtps\\n\"                                               // free-form tag\n    \"RTENDMARKERBS1001\";                                        // end marker the client looks for\n\nstatic std::string http_reply() {                               // build the full HTTP response text\n    const std::string body = kServerData;                       // the body never changes\n    return \"HTTP/1.1 200 OK\\r\\n\"                                // status line\n           \"Content-Type: text/plain\\r\\n\"                       // plain text body\n           \"Content-Length: \" + std::to_string(body.size()) + \"\\r\\n\" // exact body size\n           \"Connection: close\\r\\n\\r\\n\" + body;                  // blank line, then the body\n}                                                               // end of http_reply\n\nvoid https_run() {                                              // runs forever on its own thread\n#ifdef _WIN32                                                   // Windows needs WSAStartup once\n    WSADATA wsa;                                                // filled by WSAStartup\n    WSAStartup(MAKEWORD(2, 2), &wsa);                           // request Winsock 2.2\n#endif                                                          // end of Windows setup\n    SSL_CTX *ctx = SSL_CTX_new(TLS_server_method());            // TLS settings shared by all connections\n    if (!ctx) return;                                           // OpenSSL failed to start\n    SSL_CTX_set_min_proto_version(ctx, TLS1_2_VERSION);         // refuse anything older than TLS 1.2\n\n    if (SSL_CTX_use_certificate_file(ctx, \"resources/ctx/server.crt\", SSL_FILETYPE_PEM) != 1 || // load the certificate\n        SSL_CTX_use_PrivateKey_file(ctx, \"resources/ctx/server.key\", SSL_FILETYPE_PEM) != 1) {  // load its private key\n        std::fprintf(stderr, \"https: cannot read resources/ctx/server.crt|key\\n\"); // tell the user which files\n        return;                                                 // without a certificate TLS cannot work\n    }                                                           // end of certificate check\n\n    socket_t listener = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP); // a TCP socket\n    if (listener == INVALID_SOCKET) return;                     // could not create it\n    int enable = 1;                                             // \"yes\" for the option below\n    setsockopt(listener, SOL_SOCKET, SO_REUSEADDR, reinterpret_cast<const char *>(&enable), sizeof enable); // allow quick restarts\n\n    sockaddr_in addr{};                                         // where to listen\n    addr.sin_family = AF_INET;                                  // IPv4\n    addr.sin_addr.s_addr = INADDR_ANY;                          // every network interface\n    addr.sin_port = htons(443);                                 // HTTPS port, needs admin/root rights\n\n    if (bind(listener, reinterpret_cast<sockaddr *>(&addr), sizeof addr) != 0) { // claim the port\n        std::fprintf(stderr, \"https: cannot bind :443 (run elevated)\\n\"); // usually missing permissions\n        return;                                                 // give up\n    }                                                           // end of bind check\n    listen(listener, 16);                                       // allow 16 waiting connections\n\n    for (;;) {                                                  // serve clients forever\n        socket_t fd = accept(listener, nullptr, nullptr);       // wait for one client\n        if (fd == INVALID_SOCKET) continue;                     // failed accept, try again\n        SSL *ssl = SSL_new(ctx);                                // TLS state for this client\n        SSL_set_fd(ssl, static_cast<int>(fd));                  // attach the socket\n        if (SSL_accept(ssl) <= 0) {                             // TLS handshake failed (e.g. \"unknown ca\")\n            SSL_free(ssl);                                      // free TLS state\n            CLOSE_SOCKET(fd);                                   // close the socket\n            continue;                                           // next client\n        }                                                       // end of handshake check\n        char request[1024];                                     // buffer for the POST we ignore\n        SSL_read(ssl, request, sizeof request);                 // read it so the client is happy\n        const std::string reply = http_reply();                 // the answer never changes\n        SSL_write(ssl, reply.data(), static_cast<int>(reply.size())); // send it\n        SSL_shutdown(ssl);                                      // close TLS politely\n        SSL_free(ssl);                                          // free TLS state\n        CLOSE_SOCKET(fd);                                       // close the socket\n    }                                                           // end of serve loop\n}                                                               // end of https_run\n";

export const serverDataPhp = "server|127.0.0.1\nport|17091\ntype|1\ntype2|1\n#maint|Server under maintenance. Please try again later.\nloginurl|127.0.0.1\nmeta|gtps\nRTENDMARKERBS1001";

export const schemaSql = "CREATE DATABASE IF NOT EXISTS gtps CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci; -- the database the server connects to\nUSE gtps;                                                       -- work inside it\nCREATE TABLE IF NOT EXISTS accounts (                           -- one row per player\n    user_id       INT AUTO_INCREMENT PRIMARY KEY,               -- unique id\n    growid        VARCHAR(18) NOT NULL UNIQUE,                  -- login name, no duplicates\n    password_hash CHAR(64)    NOT NULL,                         -- sha256(salt + password) as hex\n    salt          CHAR(32)    NOT NULL,                         -- random salt as hex\n    gems          BIGINT      NOT NULL DEFAULT 0,               -- gem balance\n    level         INT         NOT NULL DEFAULT 1,               -- player level\n    created_at    TIMESTAMP   DEFAULT CURRENT_TIMESTAMP         -- when it was created\n) ENGINE = InnoDB;                                              -- InnoDB supports transactions\nCREATE TABLE IF NOT EXISTS worlds (                             -- one row per world\n    name       VARCHAR(24) NOT NULL PRIMARY KEY,                -- upper-case world name\n    owner_id   INT         NOT NULL DEFAULT 0,                  -- owner account id\n    tiles      LONGBLOB,                                        -- 6000 tiles x 8 bytes\n    updated_at TIMESTAMP   DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP -- last save time\n) ENGINE = InnoDB;                                              -- InnoDB again\n";

export const dbHpp = "#pragma once                                                    // include once\n#include \"net.hpp\"                                              // u8, i32, std::string, std::vector\n\nstruct account {                                                // what we need to know about a logged-in account\n    i32 user_id = 0;                                            // primary key in the accounts table\n    std::string growid;                                         // account name\n};                                                              // end of account\n\nbool db_open(const char *host, const char *user, const char *password, const char *database); // connect once at startup\nbool db_exists(const std::string &growid);                      // does this name exist?\nbool db_create(const std::string &growid, const std::string &password, account &out); // register a new account\nbool db_login(const std::string &growid, const std::string &password, account &out); // check a password\nbool db_world_load(const std::string &name, i32 &owner_id, std::vector<u8> &tiles); // read a saved world\nvoid db_world_save(const std::string &name, i32 owner_id, const std::vector<u8> &tiles); // write a world\n";

export const dbCpp = "#include \"db.hpp\"                                               // our declarations\n#include <cstdio>                                               // fprintf\n#include <cstring>                                              // strlen\n#include <mysql/mysql.h>                                        // MariaDB / MySQL client API\n#include <openssl/evp.h>                                        // SHA-256\n#include <openssl/rand.h>                                       // random salt\n\nstatic MYSQL *g_db = nullptr;                                   // the one database connection (main thread only)\n\nstatic std::string to_hex(const unsigned char *data, unsigned length) { // bytes -> hex text\n    static const char *digits = \"0123456789abcdef\";             // hex digits\n    std::string out;                                            // result\n    out.reserve(length * 2);                                    // two characters per byte\n    for (unsigned i = 0; i < length; ++i) {                     // each byte\n        out.push_back(digits[data[i] >> 4]);                    // high 4 bits\n        out.push_back(digits[data[i] & 0x0f]);                  // low 4 bits\n    }                                                           // end of loop\n    return out;                                                 // hex string\n}                                                               // end of to_hex\n\nstatic std::string sha256_hex(const std::string &input) {       // SHA-256 of a string, as hex\n    unsigned char digest[32];                                   // 32 bytes = 256 bits\n    unsigned int length = 0;                                    // filled by OpenSSL\n    EVP_Digest(input.data(), input.size(), digest, &length, EVP_sha256(), nullptr); // compute the hash\n    return to_hex(digest, length);                              // hex text\n}                                                               // end of sha256_hex\n\nstatic std::string random_salt() {                              // 16 random bytes as hex\n    unsigned char raw[16];                                      // random bytes\n    if (RAND_bytes(raw, sizeof raw) != 1) return std::string(32, '0'); // fallback only if OpenSSL fails\n    return to_hex(raw, sizeof raw);                             // hex text\n}                                                               // end of random_salt\n\nstruct stmt {                                                   // small helper that prepares and always closes a statement\n    MYSQL_STMT *s;                                              // the prepared statement\n    explicit stmt(const char *sql) : s(mysql_stmt_init(g_db)) { // create it\n        mysql_stmt_prepare(s, sql, (unsigned long)std::strlen(sql)); // compile the SQL text\n    }                                                           // end of constructor\n    ~stmt() { mysql_stmt_close(s); }                            // closed automatically when it goes out of scope\n};                                                              // end of stmt\n\nstatic void bind_text(MYSQL_BIND &b, const std::string &v) {    // fill an input bind with a string\n    b = MYSQL_BIND{};                                           // clear it first\n    b.buffer_type = MYSQL_TYPE_STRING;                          // it is text\n    b.buffer = (void *)v.data();                                // point at the characters\n    b.buffer_length = (unsigned long)v.size();                  // how many\n}                                                               // end of bind_text\n\nbool db_open(const char *host, const char *user, const char *password, const char *database) { // connect\n    g_db = mysql_init(nullptr);                                 // allocate the connection object\n    if (!g_db) return false;                                    // out of memory\n    if (!mysql_real_connect(g_db, host, user, password, database, 3306, nullptr, 0)) { // try to connect on port 3306\n        std::fprintf(stderr, \"mysql: %s\\n\", mysql_error(g_db)); // print the reason\n        return false;                                           // failed\n    }                                                           // end of connect check\n    mysql_set_character_set(g_db, \"utf8mb4\");                   // full Unicode\n    return true;                                                // connected\n}                                                               // end of db_open\n\nbool db_exists(const std::string &growid) {                     // is the name taken?\n    stmt q(\"SELECT 1 FROM accounts WHERE growid = ? LIMIT 1\");  // ? is replaced safely, no SQL injection\n    MYSQL_BIND in{};                                            // one input\n    bind_text(in, growid);                                      // the name\n    mysql_stmt_bind_param(q.s, &in);                            // attach it\n    mysql_stmt_execute(q.s);                                    // run\n    mysql_stmt_store_result(q.s);                               // buffer the rows so we can count them\n    return mysql_stmt_num_rows(q.s) > 0;                        // any row means it exists\n}                                                               // end of db_exists\n\nbool db_create(const std::string &growid, const std::string &password, account &out) { // register\n    const std::string salt = random_salt();                     // a new salt per account\n    const std::string hash = sha256_hex(salt + password);       // hash(salt + password)\n    stmt q(\"INSERT INTO accounts (growid, password_hash, salt) VALUES (?, ?, ?)\"); // insert statement\n    MYSQL_BIND in[3]{};                                         // three inputs\n    bind_text(in[0], growid);                                   // name\n    bind_text(in[1], hash);                                     // hashed password\n    bind_text(in[2], salt);                                     // salt\n    mysql_stmt_bind_param(q.s, in);                             // attach them\n    if (mysql_stmt_execute(q.s) != 0) return false;             // duplicate name or other error\n    out.user_id = (i32)mysql_stmt_insert_id(q.s);               // the new AUTO_INCREMENT id\n    out.growid = growid;                                        // remember the name\n    return true;                                                // created\n}                                                               // end of db_create\n\nbool db_login(const std::string &growid, const std::string &password, account &out) { // verify a password\n    stmt q(\"SELECT user_id, password_hash, salt FROM accounts WHERE growid = ? LIMIT 1\"); // lookup\n    MYSQL_BIND in{};                                            // one input\n    bind_text(in, growid);                                      // the name\n    mysql_stmt_bind_param(q.s, &in);                            // attach it\n    mysql_stmt_execute(q.s);                                    // run\n    i32 user_id = 0;                                            // output: id\n    char hash[65]{};                                            // output: 64 hex chars + NUL\n    char salt[33]{};                                            // output: 32 hex chars + NUL\n    unsigned long hash_len = 0, salt_len = 0;                   // real lengths returned by the server\n    MYSQL_BIND res[3]{};                                        // three outputs\n    res[0].buffer_type = MYSQL_TYPE_LONG; res[0].buffer = &user_id; // id\n    res[1].buffer_type = MYSQL_TYPE_STRING; res[1].buffer = hash; res[1].buffer_length = sizeof hash; res[1].length = &hash_len; // hash\n    res[2].buffer_type = MYSQL_TYPE_STRING; res[2].buffer = salt; res[2].buffer_length = sizeof salt; res[2].length = &salt_len; // salt\n    mysql_stmt_bind_result(q.s, res);                           // attach outputs\n    if (mysql_stmt_fetch(q.s) != 0) return false;               // no such account\n    const std::string expected(hash, hash_len);                 // stored hash\n    const std::string computed = sha256_hex(std::string(salt, salt_len) + password); // hash what the user typed\n    if (computed != expected) return false;                     // wrong password\n    out.user_id = user_id;                                      // fill the result\n    out.growid = growid;                                        // fill the result\n    return true;                                                // logged in\n}                                                               // end of db_login\n\nbool db_world_load(const std::string &name, i32 &owner_id, std::vector<u8> &tiles) { // read a world row\n    stmt q(\"SELECT owner_id, tiles FROM worlds WHERE name = ? LIMIT 1\"); // lookup\n    MYSQL_BIND in{};                                            // one input\n    bind_text(in, name);                                        // world name\n    mysql_stmt_bind_param(q.s, &in);                            // attach it\n    mysql_stmt_execute(q.s);                                    // run\n    tiles.assign(6000 * 8, 0);                                  // room for 6000 tiles x 8 bytes\n    unsigned long length = 0;                                   // real blob size\n    MYSQL_BIND res[2]{};                                        // two outputs\n    res[0].buffer_type = MYSQL_TYPE_LONG; res[0].buffer = &owner_id; // owner\n    res[1].buffer_type = MYSQL_TYPE_BLOB; res[1].buffer = tiles.data(); res[1].buffer_length = (unsigned long)tiles.size(); res[1].length = &length; // tiles\n    mysql_stmt_bind_result(q.s, res);                           // attach outputs\n    if (mysql_stmt_fetch(q.s) != 0) return false;               // world not saved yet\n    tiles.resize(length < tiles.size() ? length : tiles.size()); // trim to the real size\n    return true;                                                // loaded\n}                                                               // end of db_world_load\n\nvoid db_world_save(const std::string &name, i32 owner_id, const std::vector<u8> &tiles) { // upsert a world\n    stmt q(\"INSERT INTO worlds (name, owner_id, tiles) VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE owner_id = VALUES(owner_id), tiles = VALUES(tiles)\"); // insert or update\n    std::vector<u8> copy = tiles;                               // bind needs a non-const pointer\n    MYSQL_BIND in[3]{};                                         // three inputs\n    bind_text(in[0], name);                                     // name\n    in[1].buffer_type = MYSQL_TYPE_LONG; in[1].buffer = &owner_id; // owner\n    in[2].buffer_type = MYSQL_TYPE_BLOB; in[2].buffer = copy.data(); in[2].buffer_length = (unsigned long)copy.size(); // tiles\n    mysql_stmt_bind_param(q.s, in);                             // attach them\n    mysql_stmt_execute(q.s);                                    // run\n}                                                               // end of db_world_save\n";

export const loginCpp = "#include \"db.hpp\"                                               // accounts\n#include \"items.hpp\"                                            // items hash for the logon reply\n#include \"net.hpp\"                                              // packet helpers\n\n#include <cctype>                                               // toupper\n#include <cstdlib>                                              // atoi\n\nstatic std::string base64_decode(const std::string &in) {       // ltoken is base64 text\n    static const std::string table = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\"; // base64 alphabet\n    std::string out;                                            // decoded bytes\n    int value = 0;                                              // bit accumulator\n    int bits = -8;                                              // how many bits are ready minus 8\n    for (const unsigned char c : in) {                          // each input character\n        if (c == '=') break;                                    // padding ends the data\n        const std::size_t index = table.find(char(c));          // 0..63\n        if (index == std::string::npos) continue;               // ignore unknown characters\n        value = (value << 6) + int(index);                      // add 6 bits\n        bits += 6;                                              // we now hold 6 more bits\n        if (bits >= 0) {                                        // a full byte is ready\n            out.push_back(char((value >> bits) & 0xff));        // take it\n            bits -= 8;                                          // 8 bits used\n        }                                                       // end of byte check\n    }                                                           // end of loop\n    return out;                                                 // decoded text\n}                                                               // end of base64_decode\n\nbool on_login(peer *p, ENetPeer *ep, const std::string &text) { // first connection: login with token\n    const std::string decoded = base64_decode(field(text, \"ltoken\")); // \"_token=..&growId=NAME&password=PASS\"\n    const std::string growid = field(decoded, \"growId\");        // the name\n    const std::string password = field(decoded, \"password\");    // the password\n    if (growid.empty() || password.empty()) {                   // missing data\n        send_text(ep, 3, \"action|logon_fail\\n\");                // reject\n        return false;                                           // not logged in\n    }                                                           // end of empty check\n    account acc{};                                              // filled on success\n    if (!db_login(growid, password, acc)) {                     // wrong password or new name\n        if (db_exists(growid) || !db_create(growid, password, acc)) { // wrong password, or creating failed\n            send_text(ep, 3, \"action|logon_fail\\n\");            // reject\n            return false;                                       // not logged in\n        }                                                       // end of reject\n        send_call(ep, -1, { Vstr(\"OnConsoleMessage\"), Vstr(\"New account created: \" + growid) }); // first login = register\n    }                                                           // end of account handling\n    p->user_id = acc.user_id;                                   // remember who this is\n    p->growid = acc.growid;                                     // remember the name\n    p->inventory = { {18, 1}, {32, 1}, {2, 200} };              // starter backpack: fist, wrench, 200 dirt\n    send_call(ep, -1, { Vstr(\"OnSendToServer\"), Vnum(17091), Vnum(0), Vnum(acc.user_id), Vstr(\"127.0.0.1|0|0\"), Vnum(1), Vstr(acc.growid) }); // tell the client to reconnect\n    return true;                                                // logged in\n}                                                               // end of on_login\n\nvoid on_logon(peer *p, ENetPeer *ep, const std::string &text) { // second connection: tankIDName\n    if (p->user_id == 0) return;                                // no login happened on this connection\n    const std::string user = field(text, \"user\");               // the client repeats the user id\n    if (!user.empty()) p->user_id = std::atoi(user.c_str());    // trust it only for this learning server\n    send_call(ep, -1, {                                         // this call lets the client leave the login screen\n        Vstr(\"OnSuperMainStartAcceptLogonHrdxs47254722215a\"),   // the function name\n        Vuint(g_items.hash),                                    // hash of OUR items.dat, a mismatch makes the client request it\n        Vstr(\"ubistatic-a.akamaihd.net\"),                       // CDN host (unused by a private server)\n        Vstr(\"0098/01020126/cache/\"),                           // CDN cache path\n        Vstr(\"\"),                                               // list of blocked apps, empty is fine\n        Vstr(\"proto=225|choosemusic=audio/mp3/about_theme.mp3|active_holiday=0|server_tick=0|isPayingUser=1|usingStoreNavigation=1|enableInventoryTab=1|bigBackpack=1\"), // client feature flags\n    });                                                         // end of call\n    send_call(ep, -1, { Vstr(\"OnConsoleMessage\"), Vstr(\"Logged in as \" + p->growid) }); // greeting in the console\n    send_call(ep, -1, { Vstr(\"OnSetBux\"), Vnum(0) });           // gem counter\n    send_call(ep, -1, { Vstr(\"OnRequestWorldSelectMenu\") });    // show the world menu\n}                                                               // end of on_logon\n\nvoid on_action(peer *p, ENetPeer *ep, const std::string &text) { // text actions from message type 3\n    if (text.rfind(\"action|refresh_item_data\", 0) == 0) {       // client asks for items.dat\n        send_call(ep, -1, { Vstr(\"OnConsoleMessage\"), Vstr(\"One moment, updating item data...\") }); // user feedback\n        send_items(ep);                                         // send the file\n        return;                                                 // handled\n    }                                                           // end of refresh_item_data\n    if (text.rfind(\"action|enter_game\", 0) == 0) {              // client finished loading\n        send_call(ep, -1, { Vstr(\"OnRequestWorldSelectMenu\") }); // show the menu\n        return;                                                 // handled\n    }                                                           // end of enter_game\n    if (text.rfind(\"action|join_request\", 0) == 0) {            // player typed a world name\n        std::string name = field(text, \"name\");                 // the typed name\n        for (char &c : name) c = char(std::toupper((unsigned char)c)); // world names are uppercase\n        on_join(p, ep, name);                                   // enter it\n        return;                                                 // handled\n    }                                                           // end of join_request\n    if (text.rfind(\"action|quit_to_exit\", 0) == 0 || text.rfind(\"action|quit\", 0) == 0) { // leave the world\n        on_leave(p, ep);                                        // remove from the world\n        send_call(ep, -1, { Vstr(\"OnRequestWorldSelectMenu\") }); // back to the menu\n    }                                                           // end of quit\n}                                                               // end of on_action\n";

export const worldHpp = "#pragma once                                                    // include once\n#include \"net.hpp\"                                              // blob, peer, i32 ...\n#include <chrono>                                               // damage timer\n\nstruct tile {                                                   // one square of a world\n    u16 fg = 0;                                                 // foreground item id (0 = empty)\n    u16 bg = 0;                                                 // background item id (0 = empty)\n    u8 state[4] = {0, 0, 0, 0};                                 // flags, rotation ...\n    u8 hits = 0;                                                // punches taken, memory only\n    std::chrono::steady_clock::time_point last_hit{};           // time of the last punch, memory only\n};                                                              // end of tile\n\nstruct world {                                                  // one world kept in memory while it is used\n    std::string name;                                           // upper-case world name\n    i32 owner_id = 0;                                           // account id of the owner (0 = nobody)\n    std::vector<tile> tiles;                                    // 100 * 60 tiles, row by row\n    float spawn_x = 50 * 32.f + 16.f;                           // spawn point in pixels (tile 50 * 32)\n    float spawn_y = 36 * 32.f + 16.f;                           // spawn point in pixels (tile 36 * 32)\n};                                                              // end of world\n\ninline constexpr i32 kWidth = 100;                              // tiles per row\ninline constexpr i32 kHeight = 60;                              // rows per world\n\ninline int cord(i32 x, i32 y) { return y * kWidth + x; }        // (x, y) -> index, rows are 100 wide\n\nworld *world_get(const std::string &name);                      // load from the cache or DB, create when new\nvoid world_save(const world &w);                                // write to the database\nblob serialize_world(const world &w);                           // SEND_MAP_DATA payload\n";

export const worldCpp = "#include \"world.hpp\"                                            // our declarations\n#include \"db.hpp\"                                               // saving and loading\n#include \"items.hpp\"                                            // nothing used directly, kept for future tile rules\n#include <format>                                               // std::format for the OnSpawn text\n#include <unordered_map>                                        // the world cache\n\nstatic std::unordered_map<std::string, world> g_worlds;         // worlds currently in memory\nstatic i32 g_next_netid = 1;                                    // netids are handed out one by one\n\nstatic blob serialize_tiles(const world &w) {                   // 8 bytes per tile\n    blob b;                                                     // output\n    for (const tile &t : w.tiles) {                             // every tile in order\n        b.i16v(t.fg);                                           // foreground id\n        b.i16v(t.bg);                                           // background id\n        for (const u8 s : t.state) b.u8v(s);                    // 4 flag bytes\n    }                                                           // end of loop\n    return b;                                                   // bytes\n}                                                               // end of serialize_tiles\n\nstatic void deserialize_tiles(world &w, const std::vector<u8> &bytes) { // inverse of serialize_tiles\n    w.tiles.assign(kWidth * kHeight, tile{});                   // start with 6000 empty tiles\n    for (std::size_t i = 0, at = 0; i < w.tiles.size() && at + 8 <= bytes.size(); ++i, at += 8) { // 8 bytes each\n        std::memcpy(&w.tiles[i].fg, bytes.data() + at, 2);      // foreground\n        std::memcpy(&w.tiles[i].bg, bytes.data() + at + 2, 2);  // background\n        std::memcpy(w.tiles[i].state, bytes.data() + at + 4, 4); // flags\n    }                                                           // end of loop\n}                                                               // end of deserialize_tiles\n\nworld *world_get(const std::string &name) {                     // the only way to get a world\n    auto found = g_worlds.find(name);                           // already in memory?\n    if (found != g_worlds.end()) return &found->second;         // yes, reuse it\n    world w;                                                    // otherwise build one\n    w.name = name;                                              // set the name\n    std::vector<u8> bytes;                                      // raw saved tiles\n    if (db_world_load(name, w.owner_id, bytes)) {               // saved before?\n        deserialize_tiles(w, bytes);                            // yes: decode it\n    } else {                                                    // brand new world\n        w.tiles.assign(kWidth * kHeight, tile{});               // empty map\n        for (i32 x = 0; x < kWidth; ++x) w.tiles[cord(x, 37)].fg = 8; // a row of bedrock under the door\n        w.tiles[cord(50, 36)].fg = 6;                           // the main door\n        world_save(w);                                          // save it right away\n    }                                                           // end of new-world branch\n    return &(g_worlds[name] = std::move(w));                    // store in the cache and return a stable pointer\n}                                                               // end of world_get\n\nvoid world_save(const world &w) {                               // persist a world\n    db_world_save(w.name, w.owner_id, serialize_tiles(w).bytes); // blob = all tiles\n}                                                               // end of world_save\n\nblob serialize_world(const world &w) {                          // SEND_MAP_DATA payload\n    blob b;                                                     // output\n    b.i16v(0x00);                                               // version\n    b.i32v(0x00);                                               // flags\n    b.i16v(i32(w.name.size()));                                 // name length\n    b.bytes.insert(b.bytes.end(), w.name.begin(), w.name.end()); // name\n    b.i32v(kWidth);                                             // width in tiles\n    b.i32v(kHeight);                                            // height in tiles\n    b.i16v(i32(w.tiles.size()));                                // tile count (6000)\n    b.i32v(0x00);                                               // unknown\n    b.i16v(0x00);                                               // unknown\n    b.u8v(0x00);                                                // unknown\n    b.append(serialize_tiles(w));                               // the tiles\n    b.i32v(0x00); b.i32v(0x00); b.i32v(0x00);                   // unknown trailer\n    b.i32v(0x00);                                               // dropped objects count\n    b.i32v(0x00);                                               // last drop uid\n    return b;                                                   // payload\n}                                                               // end of serialize_world\n\nstatic std::string spawn_text(const peer *p, bool local) {      // text for OnSpawn\n    return std::format(\"spawn|avatar\\nnetID|{}\\nuserID|{}\\ncolrect|0|0|20|30\\nposXY|{}|{}\\nname|{}\\ncountry|us\\ninvis|0\\nmstate|1\\nsmstate|0\\n{}\", // fixed layout\n                       p->netid, p->user_id, p->x, p->y, p->growid, local ? \"type|local\\n\" : \"\"); // \"type|local\" marks your own avatar\n}                                                               // end of spawn_text\n\nvoid on_join(peer *p, ENetPeer *ep, const std::string &name) { // player entered a world name\n    if (name.empty() || name.size() > 24) {                     // bad name\n        send_call(ep, -1, { Vstr(\"OnFailedToEnterWorld\") });    // tell the client\n        return;                                                 // stop\n    }                                                           // end of name check\n    on_leave(p, ep);                                            // leave the old world first (does nothing in the menu)\n    world *w = world_get(name);                                 // load or create it\n    p->world = name;                                            // remember where the player is\n    p->netid = g_next_netid++;                                  // a fresh id for this visit\n    p->x = w->spawn_x;                                          // spawn position\n    p->y = w->spawn_y;                                          // spawn position\n\n    game_packet map;                                            // the map packet\n    map.type = 0x04;                                            // 0x04 = SEND_MAP_DATA\n    map.netid = p->netid;                                       // who receives it\n    map.state = 0x08;                                           // extra data follows\n    map.extra = serialize_world(*w);                            // the tiles\n    send_raw(ep, map.encode());                                 // ship the map\n\n    for (size_t i = 0; i < g_host->peerCount; ++i) {            // show everyone already inside to the new player\n        ENetPeer *other = &g_host->peers[i];                    // one connection slot\n        if (other == ep || other->state != ENET_PEER_STATE_CONNECTED) continue; // skip self and empty slots\n        const peer *op = static_cast<peer *>(other->data);      // their data\n        if (op && op->world == name) send_call(ep, op->netid, { Vstr(\"OnSpawn\"), Vstr(spawn_text(op, false)) }); // spawn them for us\n    }                                                           // end of loop\n\n    send_call(ep, p->netid, { Vstr(\"OnSpawn\"), Vstr(spawn_text(p, true)) }); // spawn ourselves (local avatar)\n    send_call(ep, p->netid, { Vstr(\"OnSetPos\"), Vvec(p->x, p->y) }); // place the camera\n    send_inventory(ep, p);                                      // fill the backpack\n    send_call(ep, -1, { Vstr(\"OnConsoleMessage\"), Vstr(\"World \" + name + \" entered.\") }); // console message\n\n    broadcast_world(name, make_call(p->netid, { Vstr(\"OnSpawn\"), Vstr(spawn_text(p, false)) }), ep); // tell everyone else about the newcomer\n}                                                               // end of on_join\n\nvoid on_leave(peer *p, ENetPeer *ep) {                          // leaving a world (quit, join another, disconnect)\n    if (p->world.empty()) return;                               // not in a world\n    const blob gone = make_call(p->netid, { Vstr(\"OnRemove\"), Vstr(\"netID|\" + std::to_string(p->netid) + \"\\n\") }); // OnRemove call\n    broadcast_world(p->world, gone, ep);                        // tell the others\n    p->world.clear();                                           // we are in the menu now\n}                                                               // end of on_leave\n";

export const tilesCpp = "#include \"world.hpp\"                                            // world and tile\n#include \"items.hpp\"                                            // hits, type, hit_reset from items.dat\n\nstatic blob tile_update(const peer *p, i32 tx, i32 ty, const tile &t) { // SEND_TILE_UPDATE_DATA packet bytes\n    game_packet upd;                                            // wrap it\n    upd.type = 0x05;                                            // 0x05 = SEND_TILE_UPDATE_DATA\n    upd.netid = p->netid;                                       // who changed it\n    upd.state = 0x08;                                           // extra data follows\n    upd.tile_x = tx;                                            // tile x\n    upd.tile_y = ty;                                            // tile y\n    upd.extra.i16v(t.fg);                                       // new foreground\n    upd.extra.i16v(t.bg);                                       // new background\n    for (const u8 s : t.state) upd.extra.u8v(s);                // flags\n    upd.extra.u8v(0x00);                                        // object type: none\n    return upd.encode();                                        // bytes\n}                                                               // end of tile_update\n\nstatic blob tile_damage(const peer *p, i32 tx, i32 ty, u8 hits) { // the cracking animation\n    game_packet dmg;                                            // wrap it\n    dmg.type = (1 << 24) | 0x08;                                // 0x08 = TILE_APPLY_DAMAGE, build range 1 in the top byte\n    dmg.netid = p->netid;                                       // who punched\n    dmg.tile_x = tx;                                            // tile x\n    dmg.tile_y = ty;                                            // tile y\n    dmg.extra_f = float(hits);                                  // damage level\n    return dmg.encode();                                        // bytes\n}                                                               // end of tile_damage\n\nvoid on_tile_change(peer *p, ENetPeer *ep, const game_packet &gp) { // type 0x03: punch or place\n    if (p->world.empty()) return;                               // not in a world\n    if (gp.tile_x < 0 || gp.tile_x >= kWidth) return;           // outside the map (x)\n    if (gp.tile_y < 0 || gp.tile_y >= kHeight) return;          // outside the map (y)\n    world *w = world_get(p->world);                             // the world the player is in\n    tile &t = w->tiles[cord(gp.tile_x, gp.tile_y)];             // the tile that was clicked\n    const u16 held = u16(gp.id);                                // the item used (18 fist, 32 wrench, or a block)\n\n    if (held == 32) return;                                     // wrench: nothing to do in this starter\n\n    if (held == 18) {                                           // fist = punch\n        const u16 target = t.fg ? t.fg : t.bg;                  // break the foreground first, then the background\n        if (target == 0) return;                                // nothing to punch\n        const item_info &info = id_to_item(target);             // rules come from items.dat\n        if (info.type == T_MAIN_DOOR || info.type == T_STRONG || target == 8) return; // unbreakable blocks\n        const u8 needed = info.hits ? info.hits : 1;            // at least one punch\n        const auto now = std::chrono::steady_clock::now();      // current time\n        if (info.hit_reset > 0 && now - t.last_hit > std::chrono::seconds(info.hit_reset)) t.hits = 0; // damage healed\n        t.last_hit = now;                                       // remember this punch\n        if (++t.hits < needed) {                                // not broken yet\n            broadcast_world(p->world, tile_damage(p, gp.tile_x, gp.tile_y, t.hits), nullptr); // everyone sees the crack\n            return;                                             // wait for more punches\n        }                                                       // end of damage branch\n        if (t.fg) t.fg = 0; else t.bg = 0;                      // the layer we hit is gone\n        t.hits = 0;                                             // reset the counter\n        if (p->inventory[target] < 200) p->inventory[target]++; // the block goes to the backpack (no drops yet)\n        world_save(*w);                                         // persist the change\n        broadcast_world(p->world, tile_update(p, gp.tile_x, gp.tile_y, t), nullptr); // everyone sees the empty tile\n        send_inventory(ep, p);                                  // refresh our backpack\n        return;                                                 // done\n    }                                                           // end of punch\n\n    if (held == 0) return;                                      // item 0 is never placeable\n    auto have = p->inventory.find(held);                        // do we carry it?\n    if (have == p->inventory.end() || have->second == 0) return; // no: ignore the packet\n    const item_info &info = id_to_item(held);                   // rules from items.dat\n    if (info.type == T_CLOTHING || info.type == T_CONSUMEABLE) return; // not placeable\n    if (info.type == T_BACKGROUND) {                            // background blocks use the bg layer\n        if (t.bg != 0) return;                                  // already one there\n        t.bg = held;                                            // place it\n    } else {                                                    // everything else is a foreground block\n        if (t.fg != 0) return;                                  // one block per tile\n        t.fg = held;                                            // place it\n    }                                                           // end of layer choice\n    if (--have->second == 0) p->inventory.erase(have);          // use one up, drop the empty slot\n    world_save(*w);                                             // persist the change\n    broadcast_world(p->world, tile_update(p, gp.tile_x, gp.tile_y, t), nullptr); // everyone sees the new block\n    send_inventory(ep, p);                                      // refresh our backpack\n}                                                               // end of on_tile_change\n";

